-- M2 application records (contracts/database/entities.md). Text ids are generated by the service.
-- JSON values are stored as text; the statements run on PostgreSQL and, for the CI tests, on SQLite.

CREATE TABLE users (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    hash TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE profiles (
    user_id TEXT PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    skills TEXT NOT NULL,
    hours REAL NOT NULL CHECK (hours >= 0 AND hours <= 168),
    team INTEGER NOT NULL CHECK (team >= 1),
    goal TEXT NOT NULL CHECK (goal IN ('startup', 'portfolio', 'course_project')),
    weeks_available INTEGER NOT NULL CHECK (weeks_available >= 0),
    compute TEXT NOT NULL CHECK (compute IN ('laptop', 'free_gpu', 'paid')),
    interests TEXT NOT NULL,
    version INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE ideas (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    source TEXT NOT NULL CHECK (source IN ('own', 'generated'))
);

CREATE TABLE idea_versions (
    id TEXT PRIMARY KEY,
    idea_id TEXT NOT NULL REFERENCES ideas (id) ON DELETE CASCADE,
    version INTEGER NOT NULL CHECK (version >= 1),
    text TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (idea_id, version)
);

CREATE TABLE verdicts (
    id TEXT PRIMARY KEY,
    version_id TEXT NOT NULL REFERENCES idea_versions (id) ON DELETE CASCADE,
    verdict TEXT NOT NULL CHECK (verdict IN ('GO', 'PIVOT', 'NO-GO', 'INSUFFICIENT_EVIDENCE')),
    score REAL NOT NULL,
    confidence REAL NOT NULL,
    document TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE dimension_scores (
    verdict_id TEXT NOT NULL REFERENCES verdicts (id) ON DELETE CASCADE,
    dimension TEXT NOT NULL,
    score REAL NOT NULL CHECK (score >= 0 AND score <= 5),
    conf REAL NOT NULL CHECK (conf >= 0 AND conf <= 1),
    evidence TEXT NOT NULL,
    UNIQUE (verdict_id, dimension)
);

-- run_id has no foreign key: an approval can be recorded before the run's trace summary exists.
CREATE TABLE approvals (
    run_id TEXT NOT NULL,
    action TEXT NOT NULL,
    decision TEXT NOT NULL,
    decided_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE traces_index (
    run_id TEXT PRIMARY KEY,
    cost REAL NOT NULL,
    latency REAL NOT NULL,
    status TEXT NOT NULL
);

CREATE TABLE conversations (
    idea_id TEXT PRIMARY KEY REFERENCES ideas (id) ON DELETE CASCADE,
    turns TEXT NOT NULL
);
